ws-running:
results = input().split()
current = 0
for result in results:
    if result == "1":
        current = current + 1
    else:
        current = 0
    print(current)

ws-best:
results = input().split()
current = 0
bestLength = 0
for result in results:
    if result == "1":
        current = current + 1
    else:
        current = 0
    if current > bestLength:
        bestLength = current
print(bestLength)

